#!/usr/bin/env bash
# Generated by tools/build-release.py. Source and releases:
# https://github.com/MachoDrone/nosana-job-finish
# No wallet handling occurs in this launcher. The CLI opens /dev/tty itself.
set -Eeuo pipefail
umask 077
unset NODE_OPTIONS NODE_PATH

TOOL_VERSION='@TOOL_VERSION@'
TOOL_SHA256='@TOOL_SHA256@'
TOOL_FILE='@TOOL_FILE@'
NODE_VERSION='24.22.2'
NODE_X64_SHA256='361718c444e49af2ca5a110c83ba6a8901143f23ab285ebbef0341f391f482a9'
NODE_ARM64_SHA256='95c264150aceb7f3437a29fd6984924f5f8d1511ea3cbd6c508b83f6c555dae2'
WORK_DIR=''
CHILD_PID=''
CYAN='' RED='' RESET=''
if [[ -t 2 && -z "${NO_COLOR+x}" && "${TERM:-dumb}" != dumb ]]; then
    CYAN=$'\033[36m'; RED=$'\033[31m'; RESET=$'\033[0m'
fi
for arg in "$@"; do
    if [[ "$arg" == --no-color ]]; then CYAN=''; RED=''; RESET=''; fi
done

say() { printf '%s%s%s\n' "$CYAN" "$*" "$RESET" >&2; }
fail() { printf '%sError: %s%s\n' "$RED" "$*" "$RESET" >&2; exit 1; }
cleanup() {
    local status=$?
    trap - EXIT
    if [[ -n "$WORK_DIR" && -d "$WORK_DIR" ]]; then rm -rf -- "$WORK_DIR"; fi
    exit "$status"
}
interrupted() {
    local signal=$1 status=$2
    trap '' INT TERM
    if [[ -n "$CHILD_PID" ]]; then
        kill -s "$signal" "$CHILD_PID" 2>/dev/null || true
        wait "$CHILD_PID" 2>/dev/null || true
    fi
    exit "$status"
}
trap cleanup EXIT
trap 'interrupted INT 130' INT
trap 'interrupted TERM 143' TERM

download() {
    local url=$1 destination=$2
    if command -v curl >/dev/null 2>&1; then
        curl --proto '=https' --tlsv1.2 --fail --location --silent --show-error \
            --connect-timeout 15 --max-time 180 --output "$destination" "$url" || return
    elif command -v wget >/dev/null 2>&1; then
        wget --https-only --quiet --timeout=30 --tries=1 --output-document="$destination" "$url" || return
    else
        fail 'curl or wget is required.'
    fi
    [[ -s "$destination" ]] || fail 'The download was empty.'
}
verify_sha256() {
    local path=$1 expected=$2 actual
    if command -v sha256sum >/dev/null 2>&1; then
        actual=$(sha256sum -- "$path"); actual=${actual%% *}
    elif command -v shasum >/dev/null 2>&1; then
        actual=$(shasum -a 256 -- "$path"); actual=${actual%% *}
    else
        fail 'sha256sum or shasum is required to verify downloads.'
    fi
    [[ "$actual" == "$expected" ]] || fail 'Download checksum did not match. Nothing from this download was run.'
}

main() {
    local platform architecture node_binary node_major node_archive node_sha status
    platform=$(uname -s)
    [[ "$platform" == Linux ]] || fail 'This launcher supports Linux only.'
    architecture=$(uname -m)
    case "$architecture" in
        x86_64|amd64) architecture=x64; node_sha=$NODE_X64_SHA256 ;;
        aarch64|arm64) architecture=arm64; node_sha=$NODE_ARM64_SHA256 ;;
        *) fail "Unsupported Linux architecture: $architecture. Supported: x86-64 and ARM64." ;;
    esac
    command -v tar >/dev/null 2>&1 || fail 'tar is required.'
    command -v gzip >/dev/null 2>&1 || fail 'gzip is required.'
    command -v mktemp >/dev/null 2>&1 || fail 'mktemp is required.'
    command -v flock >/dev/null 2>&1 || fail 'flock (from util-linux) is required. No packages were installed.'
    if ! command -v curl >/dev/null 2>&1 && ! command -v wget >/dev/null 2>&1; then
        fail 'curl or wget is required.'
    fi
    if ! command -v sha256sum >/dev/null 2>&1 && ! command -v shasum >/dev/null 2>&1; then
        fail 'sha256sum or shasum is required to verify downloads.'
    fi
    [[ "$TOOL_SHA256" =~ ^[0-9a-f]{64}$ ]] || fail 'This source launcher has not been prepared for a release.'

    WORK_DIR=$(mktemp -d "${TMPDIR:-/tmp}/nosana-job-finish.XXXXXXXX")
    node_binary=$(command -v node || true)
    node_major=''
    if [[ -n "$node_binary" ]]; then
        node_major=$("$node_binary" -p 'process.versions.node.split(".")[0]' 2>/dev/null) || node_major=''
    fi
    if [[ ! "$node_major" =~ ^[0-9]+$ ]] || (( node_major < 24 )); then
        if ! command -v getconf >/dev/null 2>&1 || ! getconf GNU_LIBC_VERSION >/dev/null 2>&1; then
            fail 'A compatible installed Node.js 24+ or a glibc-based Linux system is required.'
        fi
        node_archive="node-v${NODE_VERSION}-linux-${architecture}.tar.gz"
        say "Preparing a temporary Node.js runtime…"
        download "https://nodejs.org/dist/v${NODE_VERSION}/${node_archive}" "$WORK_DIR/node.tar.gz" \
            || fail 'Could not download Node.js. No system packages were changed.'
        verify_sha256 "$WORK_DIR/node.tar.gz" "$node_sha"
        tar -xzf "$WORK_DIR/node.tar.gz" -C "$WORK_DIR" --no-same-owner \
            || fail 'Could not extract the verified Node.js download.'
        node_binary="$WORK_DIR/node-v${NODE_VERSION}-linux-${architecture}/bin/node"
        [[ -x "$node_binary" ]] || fail 'The temporary Node.js executable is missing.'
        "$node_binary" --version >/dev/null 2>&1 \
            || fail 'The temporary Node.js runtime is not compatible with this system.'
    fi

    say "Loading Nosana Job Finish ${TOOL_VERSION}…"
    download "https://github.com/MachoDrone/nosana-job-finish/releases/download/v${TOOL_VERSION}/${TOOL_FILE}" "$WORK_DIR/tool.tar.gz" \
        || fail 'Could not download Nosana Job Finish.'
    verify_sha256 "$WORK_DIR/tool.tar.gz" "$TOOL_SHA256"
    tar -xzf "$WORK_DIR/tool.tar.gz" -C "$WORK_DIR" --no-same-owner \
        || fail 'Could not extract the verified tool download.'
    [[ -f "$WORK_DIR/nosana-job-finish/src/cli.mjs" ]] || fail 'The downloaded tool has no entry point.'

    # Avoid consuming piped Bash source as answers. Interactive input belongs
    # exclusively to the CLI's /dev/tty reader, never stdin or this launcher.
    "$node_binary" "$WORK_DIR/nosana-job-finish/src/cli.mjs" "$@" </dev/null &
    CHILD_PID=$!
    status=0
    wait "$CHILD_PID" || status=$?
    CHILD_PID=''
    return "$status"
}
main "$@"
exit "$?"
